#!/usr/bin/env python3
"""Genera src/i18n.js (diccionarios en/pt de OptimizIA). Fuente única: la tabla T de abajo (clave → (inglés, portugués)).
   Uso: python3 tools/i18n_src.py   (la portada en/pt viene de /tmp/hero.json o de app.json → i18n)"""
import json, pathlib
R = pathlib.Path(__file__).resolve().parent.parent
cfg = json.loads((R / 'app.json').read_text(encoding='utf-8'))
def hero(l):
    i = cfg['i18n'][l]; h1 = i['h1']
    import re
    h1 = re.sub(r'\*(.+?)\*', r'<em>\1</em>', h1)
    return {'title': i['title'], 'hero.eyebrow': i['eyebrow'], 'hero.h1': h1, 'hero.lede': i['lede']}

